export async function sendEmail({
  to,
  subject,
  text,
  html,
}: {
  to: string;
  subject: string;
  text: string;
  html?: string;
}) {
  const from = `${process.env.FROM_NAME || "Bangkok Days"} <${process.env.SMTP_FROM}>`;

  await transporter.sendMail({
    from,
    to,
    subject,
    text,
    html: html || text.replace(/\n/g, "<br>"),
  });
}

