          update: { canView: p.canView, canCreate: p.canCreate, canEdit: p.canEdit, canDelete: p.canDelete },
        })
      )
    )

    const permissions = await prisma.rolePermission.findMany({
      orderBy: [{ role: "asc" }, { resource: "asc" }],
    })
    return success(permissions)
  } catch (err) {
    return error(err)
  }
