const DEFAULT_FEEDS = "https://www.bangkokpost.com/rss/data/most-recent.xml\nhttps://www.thaipbsworld.com/feed/\nhttps://thethaiger.com/feed"

async function fetchRSS(feedUrl: string): Promise<{ title: string; link: string; description: string; image: string; pubDate: string }[]> {
  const res = await fetch(feedUrl)
  const xml = await res.text()
  const items: { title: string; link: string; description: string; image: string; pubDate: string }[] = []
  const itemRegex = /<item>([\s\S]*?)<\/item>/g
  let match
  while ((match = itemRegex.exec(xml)) !== null) {
    const block = match[1]
    const titleMatch = block.match(/<title><!\[CDATA\[(.*?)\]\]>|<title>(.*?)<\/title>/)
    const title = titleMatch?.[1] || titleMatch?.[2] || ""
    const link = (block.match(/<link[^>]*>([\s\S]*?)<\/link>/)?.[1] || "").replace(/^<!\[CDATA\[|\]\]>$/g, "").trim()
    const desc = block.match(/<description><!\[CDATA\[(.*?)\]\]>|<description>(.*?)<\/description>/)?.[1] || block.match(/<description>(.*?)<\/description>/)?.[1] || ""
    const image = block.match(/<enclosure[^>]+url="([^"]+)"/)?.[1] || block.match(/<media:content[^>]+url="([^"]+)"/)?.[1] || block.match(/<img[^>]+src="([^"]+)"/)?.[1] || ""
    const pubDate = block.match(/<pubDate>(.*?)<\/pubDate>/)?.[1] || ""
    if (title && link) items.push({ title, link, description: desc.replace(/<[^>]+>/g, "").slice(0, 500), image, pubDate })
  }
  return items.slice(0, 8)
}

async function getOgImage(url: string): Promise<string> {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(5000) })
    const html = await res.text()
    return html.match(/<meta[^>]+property="og:image"[^>]+content="([^"]+)"/)?.[1] ||
           html.match(/<meta[^>]+content="([^"]+)"[^>]+property="og:image"/)?.[1] || ""
  } catch { return "" }
}

async function uploadImageToCloudinary(imageUrl: string): Promise<string | null> {
  try {
    const cloudName = process.env.NEXT_PUBLIC_CLOUDINARY_CLOUD_NAME
    const apiKey = process.env.CLOUDINARY_API_KEY
    const apiSecret = process.env.CLOUDINARY_API_SECRET
    if (!cloudName || !apiKey || !apiSecret) return null

    const timestamp = Math.round(Date.now() / 1000)
    const folder = "site-bang/news"

    const { createHash } = await import("crypto")
    const signature = createHash("sha1")
      .update(`folder=${folder}&timestamp=${timestamp}${apiSecret}`)
      .digest("hex")

    const uploadForm = new FormData()
    uploadForm.append("file", imageUrl)
    uploadForm.append("api_key", apiKey)
    uploadForm.append("timestamp", timestamp.toString())
    uploadForm.append("signature", signature)
    uploadForm.append("folder", folder)

    const res = await fetch(
      `https://api.cloudinary.com/v1_1/${cloudName}/image/upload`,
      { method: "POST", body: uploadForm }
    )

    const data = await res.json()
    if (!res.ok) return null
    return data.secure_url || null
  } catch {
    return null
  }
}

async function rewriteWithAI(title: string, description: string, customPrompt?: string): Promise<{ jaTitle: string; jaContent: string; excerpt: string; slug: string; category: string } | null> {
