    console.error("[auto-news] OPENAI_API_KEY is not set")
    return null
  }

  const prompt = (customPrompt || DEFAULT_PROMPT)
    .replace("{title}", title)
    .replace("{description}", description)

  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      max_tokens: 1500,
      messages: [{ role: "user", content: prompt }],
    }),
  })

  if (!res.ok) {
    const errText = await res.text()
    console.error(`[auto-news] OpenAI error ${res.status}:`, errText)
    return null
  }
  const data = await res.json()
  const text = data.choices?.[0]?.message?.content || ""
  try {
    const json = JSON.parse(text.replace(/```json\n?|\n?```/g, "").trim())
    return { jaTitle: json.title, jaContent: json.content, excerpt: json.excerpt, slug: json.slug, category: json.category || "LIFE" }
