    return null
  }
}

// Simple similarity check using trigrams
function getSimilarity(a: string, b: string): number {
  const normalize = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "")
  const trigrams = (s: string) => {
    const n = normalize(s)
    const set = new Set<string>()
    for (let i = 0; i < n.length - 2; i++) set.add(n.slice(i, i + 3))
    return set
  }
  const setA = trigrams(a)
  const setB = trigrams(b)
  if (setA.size === 0 || setB.size === 0) return 0
  let intersection = 0
  for (const t of setA) if (setB.has(t)) intersection++
  return intersection / Math.max(setA.size, setB.size)
}

// POST: Trigger auto-news generation
export async function POST(req: NextRequest) {
  try {
    await requirePermission("auto_news", "canCreate")

    const body = await req.json().catch(() => ({}))
    const autoPublish = body.autoPublish === true
    const dateFrom = body.dateFrom ? new Date(body.dateFrom) : null
    const dateTo = body.dateTo ? new Date(body.dateTo + "T23:59:59") : null

    // Load settings from DB
    const settings = await prisma.globalSettings.findMany({
      where: { key: { in: ["news_rss_feeds", "news_ai_prompt"] } },
    })
    const feedsStr = settings.find(s => s.key === "news_rss_feeds")?.value || DEFAULT_FEEDS
    const customPrompt = settings.find(s => s.key === "news_ai_prompt")?.value || ""
    const RSS_FEEDS = feedsStr.split("\n").filter(Boolean).map(url => ({ url: url.trim(), category: "LIFE" }))

    // Load existing article titles for dedup
    const existingArticles = await prisma.article.findMany({
      where: { type: "NEWS" },
      select: { sourceUrl: true, translations: { select: { title: true, content: true }, where: { locale: "ja" } } },
    })
