function ShopListContent() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [areas, setAreas] = useState<Area[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [places, setPlaces] = useState<Place[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(Number(searchParams.get("page")) || 1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);

  // State stores IDs internally, URL uses slugs
  const [selectedArea, setSelectedArea] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("");
  const [selectedScene, setSelectedScene] = useState("");
  const [searchQuery, setSearchQuery] = useState(searchParams.get("q") || "");
  const [sortBy, setSortBy] = useState(searchParams.get("sortBy") || "displayPriority");

  // Resolve slug params → IDs once data is loaded
  useEffect(() => {
    Promise.all([getAreas(), getCategories(), getScenes()]).then(([a, c, s]) => {
      setAreas(a);
      setCategories(c);
      setScenes(s);
      // Resolve URL slugs → IDs
      const areaSlug = searchParams.get("area");
      const catSlug = searchParams.get("category");
      const sceneSlug = searchParams.get("scene");
      if (areaSlug) { const found = a.find((x: Area) => x.slug === areaSlug); if (found) setSelectedArea(found.id); }
      if (catSlug) { const found = c.find((x: Category) => x.slug === catSlug); if (found) setSelectedCategory(found.id); }
      if (sceneSlug) { const found = (s as any[]).find((x: any) => x.slug === sceneSlug); if (found) setSelectedScene(found.id); }
    });
  }, []);

  // Build slug-based URL
  const updateUrl = useCallback((ids: { areaId: string; categoryId: string; sceneId: string; q: string; sortBy: string; page: string }, currentAreas: Area[], currentCategories: Category[], currentScenes: any[]) => {
    const qs = new URLSearchParams();
    if (ids.areaId) { const s = currentAreas.find(a => a.id === ids.areaId)?.slug; if (s) qs.set("area", s); }
    if (ids.categoryId) { const s = currentCategories.find(c => c.id === ids.categoryId)?.slug; if (s) qs.set("category", s); }
    if (ids.sceneId) { const s = currentScenes.find(sc => sc.id === ids.sceneId)?.slug; if (s) qs.set("scene", s); }
    if (ids.q) qs.set("q", ids.q);
    if (ids.sortBy && ids.sortBy !== "displayPriority") qs.set("sortBy", ids.sortBy);
    if (ids.page && ids.page !== "1") qs.set("page", ids.page);
    const str = qs.toString();
    router.replace(`${pathname}${str ? `?${str}` : ""}`, { scroll: false });
  }, [router, pathname]);

  const fetchPlaces = useCallback(async () => {
    setLoading(true);
    try {
      const params: Record<string, string> = { page: String(page), limit: "12" };
      if (selectedArea) params.areaId = selectedArea;
      if (selectedCategory) params.categoryId = selectedCategory;
      if (selectedScene) params.sceneId = selectedScene;
      if (searchQuery) params.q = searchQuery;
      if (sortBy === "newest") { params.sortBy = "createdAt"; params.sortOrder = "desc"; }
      else if (sortBy === "popular") { params.sortBy = "viewCount"; params.sortOrder = "desc"; }
      else { params.sortBy = "displayPriority"; params.sortOrder = "desc"; }
      const data = await getPlaces(params);
      setPlaces(data.items);
      setTotal(data.pagination.total);
      setTotalPages(data.pagination.totalPages);
    } catch {
      setPlaces([]);
    } finally {
      setLoading(false);
    }
  }, [page, selectedArea, selectedCategory, selectedScene, searchQuery, sortBy]);

  useEffect(() => {
    fetchPlaces();
    updateUrl({ areaId: selectedArea, categoryId: selectedCategory, sceneId: selectedScene, q: searchQuery, sortBy, page: String(page) }, areas, categories, scenes);
  }, [fetchPlaces]);

  const handleFilterChange = (field: string, value: string) => {
    const newState = { areaId: selectedArea, categoryId: selectedCategory, sceneId: selectedScene, q: searchQuery, sortBy, page: "1", [field]: value };
    if (field === "areaId") setSelectedArea(value);
    if (field === "categoryId") setSelectedCategory(value);
    if (field === "sceneId") setSelectedScene(value);
    if (field === "q") setSearchQuery(value);
    if (field === "sortBy") setSortBy(value);
    setPage(1);
    updateUrl(newState, areas, categories, scenes);
  };

