// Build a proper Google Maps embed URL.
// Priority:
//  1. Coordinates (@lat,lng) in stored URL → Maps Embed API with key (no billing risk)
//  2. place_id in stored URL              → Maps Embed API place mode with key
//  3. Address text                        → OpenStreetMap embed (no API key needed)
const buildEmbedUrl = (): { url: string; type: "google" | "osm" } | null => {
  if (mapsUrl) {
    const coordMatch = mapsUrl.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
    if (coordMatch) {
      const lat = coordMatch[1];
      const lng = coordMatch[2];
      const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY || "";
      if (apiKey) {
        // Maps Embed API — coordinate mode (requires Maps Embed API enabled)
        return { url: `https://www.google.com/maps/embed/v1/view?key=${apiKey}&center=${lat},${lng}&zoom=17&maptype=roadmap`, type: "google" };
      }
      // No API key → OpenStreetMap
      return { url: `https://www.openstreetmap.org/export/embed.html?bbox=${parseFloat(lng)-0.002},${parseFloat(lat)-0.002},${parseFloat(lng)+0.002},${parseFloat(lat)+0.002}&layer=mapnik&marker=${lat},${lng}`, type: "osm" };
    }
    const placeIdMatch = mapsUrl.match(/place_id[=:]([^&/?\s]+)/);
    if (placeIdMatch) {
      const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY || "";
      if (apiKey) {
        return { url: `https://www.google.com/maps/embed/v1/place?key=${apiKey}&q=place_id:${placeIdMatch[1]}`, type: "google" };
      }
    }
  }
  // Fallback: OpenStreetMap address search (no API key needed, always works)
  if (place.address) {
    const q = encodeURIComponent(place.address + " Bangkok");
    return { url: `https://www.openstreetmap.org/export/embed.html?query=${q}&layer=mapnik`, type: "osm" };
  }
  return null;
};
const mapsEmbed = buildEmbedUrl();

